<!-- @FIGURE_UI_BEGIN -->
<label>Scan time: <output id="timeScanVal">0.25</output><input id="timeScanInput" type="range" min="0" max="1" step="0.01" value="0.25" oninput="document.getElementById('timeScanVal').value=this.value;update_timeScan(+this.value)"></label>
