// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
container.appendChild(canvas);

var activeMode = 'AM';
var scanT = 0.25;
var sampleCount = 1200;
var colors = {
  black: '#202020',
  red: '#c63e24',
  blue: '#4d66ad'
};

function signalValue(t) {
  return Math.sin(3 * Math.PI * t + 0.10);
}
function signalNorm(t) {
  return (signalValue(t) + 1) / 2;
}
function amEnvelope(t) {
  return 0.12 + 0.36 * signalNorm(t);
}
function fmFrequency(t) {
  return 10.5 + 10.5 * signalNorm(t);
}
function qWord(v, hi, mid, lo) {
  if (v > 0.66) return hi;
  if (v < 0.34) return lo;
  return mid;
}
function makeData() {
  var sig = [], am = [], fm = [];
  var phase = 0;
  var prevT = 0;
  for (var i = 0; i < sampleCount; i++) {
    var t = i / (sampleCount - 1);
    var s = signalValue(t);
    sig.push({ x: t, y: 2.68 + 0.38 * s });

    var env = amEnvelope(t);
    am.push({ x: t, y: 1.55 + env * Math.sin(2 * Math.PI * 16.2 * t + 0.20) });

    if (i > 0) {
      var dt = t - prevT;
      var fMid = fmFrequency((t + prevT) / 2);
      phase += 2 * Math.PI * fMid * dt;
    }
    fm.push({ x: t, y: 0.38 + 0.33 * Math.sin(phase + 0.12) });
    prevT = t;
  }
  return { sig: sig, am: am, fm: fm };
}
var waveData = makeData();

function roundedRectPath(ctx, x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

var educationalOverlay = {
  id: 'educationalOverlay',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx;
    var x = chart.scales.x;
    var y = chart.scales.y;
    var ca = chart.chartArea;
    var minDim = Math.min(ca.width, ca.height);
    var pad = Math.max(3, minDim * 0.012);

    ctx.save();
    var yTop, yBot, fill;
    if (activeMode === 'AM') {
      yTop = y.getPixelForValue(2.08);
      yBot = y.getPixelForValue(1.02);
      fill = 'rgba(198,62,36,0.075)';
    } else {
      yTop = y.getPixelForValue(0.86);
      yBot = y.getPixelForValue(0.00);
      fill = 'rgba(77,102,173,0.085)';
    }
    roundedRectPath(ctx, ca.left + pad, yTop, ca.right - ca.left - 2 * pad, yBot - yTop, pad * 2);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.restore();
  },
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx;
    var x = chart.scales.x;
    var y = chart.scales.y;
    var ca = chart.chartArea;
    var minDim = Math.min(ca.width, ca.height);
    var lw = Math.max(1, minDim * 0.006);
    var fontSize = Math.max(10, Math.min(15, minDim * 0.035));
    var smallFont = Math.max(9, Math.min(12, minDim * 0.029));

    ctx.save();

    function drawDecoded(base, amp) {
      ctx.beginPath();
      for (var i = 0; i < 260; i++) {
        var t = i / 259;
        var px = x.getPixelForValue(t);
        var py = y.getPixelForValue(base + amp * signalValue(t));
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.lineWidth = Math.max(1, lw * 0.72);
      ctx.strokeStyle = colors.black;
      ctx.globalAlpha = 0.92;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
    if (activeMode === 'AM') drawDecoded(2.18, 0.12);
    else drawDecoded(0.88, 0.12);

    var markerX = x.getPixelForValue(scanT);
    ctx.beginPath();
    ctx.moveTo(markerX, ca.top + 2);
    ctx.lineTo(markerX, ca.bottom - 2);
    ctx.lineWidth = Math.max(1, lw * 0.55);
    ctx.setLineDash([5, 4]);
    ctx.strokeStyle = 'rgba(40,40,40,0.55)';
    ctx.stroke();
    ctx.setLineDash([]);

    var sn = signalNorm(scanT);
    var sQual = qWord(sn, 'high', 'mid', 'low');
    var envQual = qWord(sn, 'large', 'medium', 'small');
    var spacingQual = qWord(sn, 'close', 'medium', 'wide');

    var readLines = [
      'signal: ' + sQual,
      'AM height: ' + envQual,
      'FM spacing: ' + spacingQual
    ];
    ctx.font = smallFont + 'px sans-serif';
    var maxW = 0;
    for (var r = 0; r < readLines.length; r++) maxW = Math.max(maxW, ctx.measureText(readLines[r]).width);
    var boxW = maxW + 14;
    var boxH = smallFont * 3.55;
    var boxX = markerX + 10;
    if (boxX + boxW > ca.right - 4) boxX = markerX - boxW - 10;
    boxX = Math.max(ca.left + 4, Math.min(ca.right - boxW - 4, boxX));
    var boxY = ca.top + minDim * 0.10;
    roundedRectPath(ctx, boxX, boxY, boxW, boxH, 5);
    ctx.fillStyle = 'rgba(255,255,255,0.88)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(120,120,120,0.35)';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = '#222';
    ctx.textBaseline = 'top';
    for (var j = 0; j < readLines.length; j++) {
      ctx.fillText(readLines[j], boxX + 7, boxY + 5 + j * smallFont * 1.08);
    }

    function labelText(txt, xv, yv) {
      var px = x.getPixelForValue(xv);
      var py = y.getPixelForValue(yv);
      ctx.font = fontSize + 'px sans-serif';
      var w = ctx.measureText(txt).width + 10;
      var h = fontSize + 7;
      roundedRectPath(ctx, px - 3, py - h / 2, w, h, 4);
      ctx.fillStyle = 'rgba(255,255,255,0.92)';
      ctx.fill();
      ctx.fillStyle = colors.black;
      ctx.textBaseline = 'middle';
      ctx.fillText(txt, px + 2, py);
    }
    labelText('Signal', 1.025, 2.65);
    labelText('AM', 1.025, 1.55);
    labelText('FM', 1.025, 0.38);

    function dotAt(yv, col) {
      ctx.beginPath();
      ctx.arc(markerX, y.getPixelForValue(yv), Math.max(2.2, minDim * 0.008), 0, Math.PI * 2);
      ctx.fillStyle = col;
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = Math.max(1, minDim * 0.004);
      ctx.stroke();
    }
    dotAt(2.68 + 0.38 * signalValue(scanT), colors.black);
    if (activeMode === 'AM') {
      dotAt(1.55 + amEnvelope(scanT), colors.red);
      dotAt(1.55 - amEnvelope(scanT), colors.red);
    } else {
      dotAt(0.38 + 0.33, colors.blue);
      dotAt(0.38 - 0.33, colors.blue);
    }

    ctx.restore();
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
