function refreshStyles(mode) {
  activeMode = mode;
  chart.data.datasets[1].borderColor = mode === 'AM' ? colors.red : 'rgba(198,62,36,0.58)';
  chart.data.datasets[2].borderColor = mode === 'FM' ? colors.blue : 'rgba(77,102,173,0.62)';
