  modeInput.checked = step.state.decodingMode === 'FM';
  toggle_decodingMode(modeInput.checked);

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;
}
function prevStep() { applyStep(currentStep - 1); }
function nextStep() { applyStep(currentStep + 1); }

applyStep(0);

canvas.addEventListener('mousemove', function (event) {
  var rect = canvas.getBoundingClientRect();
  var yPix = event.clientY - rect.top;
  var xPix = event.clientX - rect.left;
  var ca = chart.chartArea;
  if (!ca || xPix < ca.left || xPix > ca.right || yPix < ca.top || yPix > ca.bottom) {
    hideTooltip();
    canvas.style.cursor = 'default';
    return;
  }
  var yVal = chart.scales.y.getValueForPixel(yPix);
  var text = '';
  if (yVal > 2.25) text = 'Signal: the slow information waveform shared by both carriers.';
  else if (yVal > 1.00) text = 'AM: the carrier peaks stay evenly spaced, but their height follows the signal.';
  else text = 'FM: the carrier height stays nearly constant, but the cycle spacing changes with the signal.';
  canvas.style.cursor = 'pointer';
  showTooltip(text, event);
});
canvas.addEventListener('mouseleave', function () {
  hideTooltip();
  canvas.style.cursor = 'default';
});
canvas.addEventListener('click', function () {
  if (activeMode === 'AM') {
    showPopup('AM decoding', 'Amplitude modulation stores the message in the envelope height of the carrier. The red peaks remain evenly spaced while the black signal can be recovered by tracing their changing height.');
  } else {
    showPopup('FM decoding', 'Frequency modulation stores the message in the changing spacing of the carrier cycles. The blue wave keeps about the same height, but its cycles compress at signal crests and spread out at troughs.');
  }
});
// @FIGURE_CODE_END

