// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
container.appendChild(canvas);

var activeMode = 'AM';
var scanT = 0.25;
var overlayActive = false;
var currentStep = 0;
var sampleCount = 1400;

var colors = {
  black: '#222225',
  red: '#c63d22',
  blue: '#4f66ad'
};

function signalValue(t) {
  return Math.sin(3 * Math.PI * t + 0.35);
}
function signalNorm(t) {
  return (signalValue(t) + 1) / 2;
}
function amEnvelope(t) {
  return 0.115 + 0.355 * signalNorm(t);
}
function fmFrequency(t) {
  return 8.2 + 13.8 * signalNorm(t);
}
function qWord(v, hi, mid, lo) {
  if (v > 0.66) return hi;
  if (v < 0.34) return lo;
  return mid;
}
function roundedRectPath(ctx, x, y, w, h, r) {
  r = Math.max(0, Math.min(r, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function makeData() {
  var sig = [], am = [], fm = [];
  var phase = 0;
  var prevT = 0;
  for (var i = 0; i < sampleCount; i++) {
    var t = i / (sampleCount - 1);
    var s = signalValue(t);

    sig.push({ x: t, y: 2.70 + 0.365 * s });

    var env = amEnvelope(t);
    am.push({ x: t, y: 1.46 + env * Math.sin(2 * Math.PI * 16.25 * t + 0.12) });

    if (i > 0) {
      var mid = (t + prevT) / 2;
      phase += 2 * Math.PI * fmFrequency(mid) * (t - prevT);
    }
    fm.push({ x: t, y: 0.34 + 0.315 * Math.sin(phase + 0.10) });
    prevT = t;
  }
  return { sig: sig, am: am, fm: fm };
}

var waveData = makeData();

var guidePlugin = {
  id: 'amFmGuides',
  beforeDatasetsDraw: function (chart) {
    if (!overlayActive) return;
    var ctx = chart.ctx;
    var x = chart.scales.x;
    var y = chart.scales.y;
    var ca = chart.chartArea;
    if (!ca) return;

    var minDim = Math.min(ca.width, ca.height);
    var radius = Math.max(3, minDim * 0.018);
    var top, bot, fill;

    if (activeMode === 'AM') {
      top = y.getPixelForValue(1.99);
      bot = y.getPixelForValue(0.93);
      fill = 'rgba(198,61,34,0.065)';
    } else {
      top = y.getPixelForValue(0.77);
      bot = y.getPixelForValue(-0.09);
      fill = 'rgba(79,102,173,0.075)';
    }

    ctx.save();
    roundedRectPath(ctx, ca.left + 6, top, ca.right - ca.left - 12, bot - top, radius);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.restore();
  },
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx;
    var x = chart.scales.x;
    var y = chart.scales.y;
    var ca = chart.chartArea;
    if (!ca) return;

    var minDim = Math.min(ca.width, ca.height);
    var lineW = Math.max(1.8, Math.min(4.6, minDim * 0.010));
    var labelFont = Math.max(13, Math.min(25, minDim * 0.043));
    var smallFont = Math.max(10, Math.min(15, minDim * 0.030));

    ctx.save();

    if (overlayActive) {
      function drawDecoded(base, amp) {
        ctx.beginPath();
        for (var i = 0; i < 300; i++) {
          var t = i / 299;
          var px = x.getPixelForValue(t);
          var py = y.getPixelForValue(base + amp * signalValue(t));
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.lineWidth = Math.max(1, lineW * 0.45);
        ctx.strokeStyle = colors.black;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.stroke();
      }

      if (activeMode === 'AM') drawDecoded(2.08, 0.12);
      else drawDecoded(0.86, 0.12);

      var markerX = x.getPixelForValue(scanT);
      ctx.beginPath();
      ctx.moveTo(markerX, ca.top + 2);
      ctx.lineTo(markerX, ca.bottom - 2);
      ctx.lineWidth = Math.max(1, lineW * 0.42);
      ctx.setLineDash([5, 4]);
      ctx.strokeStyle = 'rgba(35,35,35,0.55)';
      ctx.stroke();
      ctx.setLineDash([]);

      var sn = signalNorm(scanT);
      var readLines = [
        'signal: ' + qWord(sn, 'high', 'mid', 'low'),
        'AM height: ' + qWord(sn, 'large', 'medium', 'small'),
        'FM spacing: ' + qWord(sn, 'close', 'medium', 'wide')
      ];

      ctx.font = smallFont + 'px sans-serif';
      var maxW = 0;
      for (var r = 0; r < readLines.length; r++) maxW = Math.max(maxW, ctx.measureText(readLines[r]).width);
      var boxW = maxW + 14;
      var boxH = smallFont * 3.55;
      var boxX = markerX + 10;
      if (boxX + boxW > ca.right - 6) boxX = markerX - boxW - 10;
      boxX = Math.max(ca.left + 6, Math.min(ca.right - boxW - 6, boxX));
      var boxY = y.getPixelForValue(2.78);
      if (boxY + boxH > y.getPixelForValue(2.18)) boxY = ca.top + 8;

      roundedRectPath(ctx, boxX, boxY, boxW, boxH, 4);
      ctx.fillStyle = 'rgba(255,255,255,0.88)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(120,120,120,0.35)';
      ctx.lineWidth = 1;
      ctx.stroke();

      ctx.fillStyle = '#222';
      ctx.textBaseline = 'top';
      for (var j = 0; j < readLines.length; j++) {
        ctx.fillText(readLines[j], boxX + 7, boxY + 5 + j * smallFont * 1.08);
      }

      function dotAt(yv, col) {
        ctx.beginPath();
        ctx.arc(markerX, y.getPixelForValue(yv), Math.max(2.2, minDim * 0.007), 0, Math.PI * 2);
        ctx.fillStyle = col;
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(1, minDim * 0.0035);
        ctx.stroke();
      }

      dotAt(2.70 + 0.365 * signalValue(scanT), colors.black);
      if (activeMode === 'AM') {
        dotAt(1.46 + amEnvelope(scanT), colors.red);
        dotAt(1.46 - amEnvelope(scanT), colors.red);
      } else {
        dotAt(0.34 + 0.315, colors.blue);
        dotAt(0.34 - 0.315, colors.blue);
      }
    }

    ctx.font = labelFont + 'px sans-serif';
    ctx.fillStyle = colors.black;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';

    function drawLabel(txt, xv, yv) {
      var px = x.getPixelForValue(xv);
      var py = y.getPixelForValue(yv);
      var w = ctx.measureText(txt).width;
      if (px + w > ca.right - 2) px = ca.right - w - 2;
      ctx.fillText(txt, px, py);
    }

    drawLabel('Signal', 1.025, 2.74);
    drawLabel('AM', 1.025, 1.47);
    drawLabel('FM', 1.025, 0.34);

    ctx.restore();
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [
      {
        label: 'Signal',
        data: waveData.sig,
        parsing: false,
        borderColor: colors.black,
        borderWidth: function (ctx) {
          var ca = ctx.chart.chartArea;
          if (!ca) return 4;
          return Math.max(2.6, Math.min(5.2, Math.min(ca.width, ca.height) * 0.012));
        },
        pointRadius: 0,
        tension: 0,
        borderCapStyle: 'butt',
        borderJoinStyle: 'round'
      },
      {
        label: 'AM',
        data: waveData.am,
        parsing: false,
        borderColor: colors.red,
        borderWidth: function (ctx) {
          var ca = ctx.chart.chartArea;
          if (!ca) return 4;
          return Math.max(2.4, Math.min(5.0, Math.min(ca.width, ca.height) * 0.011));
        },
        pointRadius: 0,
        tension: 0,
        borderCapStyle: 'round',
        borderJoinStyle: 'round'
      },
      {
        label: 'FM',
        data: waveData.fm,
        parsing: false,
        borderColor: colors.blue,
        borderWidth: function (ctx) {
          var ca = ctx.chart.chartArea;
          if (!ca) return 4;
          return Math.max(2.4, Math.min(5.0, Math.min(ca.width, ca.height) * 0.011));
        },
        pointRadius: 0,
        tension: 0,
        borderCapStyle: 'round',
        borderJoinStyle: 'round'
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: { duration: 160 },
    interaction: { mode: 'nearest', intersect: false },
    layout: { padding: { left: 6, right: 8, top: 2, bottom: 0 } },
    plugins: {
      legend: { display: false },
      title: { display: false },
      tooltip: { enabled: false }
    },
    scales: {
      x: {
        type: 'linear',
        min: 0,
        max: 1.145,
        display: false,
        grid: { display: false },
        border: { display: false }
      },
      y: {
        min: -0.05,
        max: 3.13,
        display: false,
        grid: { display: false },
        border: { display: false }
      }
    }
  },
  plugins: [guidePlugin]
});
window.__markRendered();

var demoSteps = [
  {
    title: 'Compare the three traces',
    narration: 'The black curve is the slow signal to be transmitted. The red AM and blue FM traces are faster carrier waves that encode that same signal in different ways.',
    state: { timeScan: 0.25, decodingMode: 'AM' }
  },
  {
    title: 'Scan an AM crest',
    narration: 'Move the time marker under a high part of the signal. The AM wave has a large envelope height there, while its peak spacing stays uniform.',
    state: { timeScan: 0.18, decodingMode: 'AM' }
  },
  {
    title: 'Scan the signal trough',
    narration: 'At the low part of the signal, the AM envelope shrinks. In contrast, the FM wave keeps the same height but its cycles spread farther apart.',
    state: { timeScan: 0.50, decodingMode: 'FM' }
  },
  {
    title: 'Decode the same message two ways',
    narration: 'Switch the decoding mode: AM reconstructs the signal from envelope height, while FM reconstructs it from changing cycle spacing. Both carriers can recover the same black signal curve.',
    state: { timeScan: 0.75, decodingMode: 'FM' }
  }
];

function setMode(mode) {
  activeMode = mode;
  var out = document.getElementById('decodingModeVal');
  if (out) out.value = mode;
}

function update_timeScan(v) {
  scanT = Math.max(0, Math.min(1, v));
  overlayActive = true;
  chart.update('none');
}

function toggle_decodingMode(on) {
  overlayActive = true;
  setMode(on ? 'FM' : 'AM');
  chart.update();
}

function applyStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[currentStep];

  scanT = +step.state.timeScan;
  setMode(step.state.decodingMode);
  overlayActive = currentStep !== 0;

  var tInput = document.getElementById('timeScanInput');
  var tVal = document.getElementById('timeScanVal');
  var modeInput = document.getElementById('decodingModeInput');

  if (tInput) tInput.value = scanT;
  if (tVal) tVal.value = scanT.toFixed(2).replace(/0$/, '').replace(/\.0$/, '');
  if (modeInput) modeInput.checked = activeMode === 'FM';

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;

  chart.update(currentStep === 0 ? 'none' : undefined);
}
function prevStep() { applyStep(currentStep - 1); }
function nextStep() { applyStep(currentStep + 1); }

applyStep(0);

canvas.addEventListener('mousemove', function (event) {
  var rect = canvas.getBoundingClientRect();
  var yPix = event.clientY - rect.top;
  var xPix = event.clientX - rect.left;
  var ca = chart.chartArea;

  if (!ca || xPix < ca.left || xPix > ca.right || yPix < ca.top || yPix > ca.bottom) {
    hideTooltip();
    canvas.style.cursor = 'default';
    return;
  }

  var yVal = chart.scales.y.getValueForPixel(yPix);
  var text;
  if (yVal > 2.15) {
    text = 'Signal: the slow information waveform that both carriers encode.';
  } else if (yVal > 0.90) {
    text = 'AM: peak spacing stays nearly uniform, while carrier height follows the signal.';
  } else {
    text = 'FM: height stays nearly constant, while cycle spacing follows the signal.';
  }
  canvas.style.cursor = 'pointer';
  showTooltip(text, event);
});
canvas.addEventListener('mouseleave', function () {
  hideTooltip();
  canvas.style.cursor = 'default';
});
canvas.addEventListener('click', function (event) {
  var rect = canvas.getBoundingClientRect();
  var yPix = event.clientY - rect.top;
  var yVal = chart.scales.y.getValueForPixel(yPix);

  if (yVal > 0.90 && yVal < 2.12) {
    overlayActive = true;
    setMode('AM');
    var modeInputA = document.getElementById('decodingModeInput');
    if (modeInputA) modeInputA.checked = false;
    chart.update();
    showPopup('Amplitude modulation', 'AM stores the message in the carrier height. The red carrier peaks stay evenly spaced, but their envelope swells and shrinks with the black signal.');
  } else if (yVal <= 0.90) {
    overlayActive = true;
    setMode('FM');
    var modeInputF = document.getElementById('decodingModeInput');
    if (modeInputF) modeInputF.checked = true;
    chart.update();
    showPopup('Frequency modulation', 'FM stores the message in the spacing of the carrier cycles. The blue wave keeps nearly constant height, but cycles compress at signal crests and spread out near troughs.');
  } else {
    showPopup('Shared signal', 'The black waveform is the information signal. AM and FM encode this same shape using different carrier properties.');
  }
});
