        dotAt(1.46 - amEnvelope(scanT), colors.red);
      } else {
        dotAt(0.34 + 0.315, colors.blue);
        dotAt(0.34 - 0.315, colors.blue);
      }
    }

    ctx.font = labelFont + 'px sans-serif';
    ctx.fillStyle = colors.black;
    ctx.textBaseline = 'middle';
