var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
container.appendChild(canvas);

var activeMode = 'AM';
var scanT = 0.25;
var overlayActive = false;
var currentStep = 0;
var sampleCount = 1800;

var colors = {
  black: '#222225',
  red: '#c63d22',
  blue: '#4f66ad'
};

function signalValue(t) {
  return Math.cos(3 * Math.PI * (t - 1 / 6));
}
function signalNorm(t) {
  return (signalValue(t) + 1) / 2;
}
function amEnvelope(t) {
  return 0.115 + 0.365 * signalNorm(t);
}
function fmFrequency(t) {
  return 7.2 + 17.8 * signalNorm(t);
}
function qWord(v, hi, mid, lo) {
  if (v > 0.66) return hi;
  if (v < 0.34) return lo;
  return mid;
}
function roundedRectPath(ctx, x, y, w, h, r) {
  r = Math.max(0, Math.min(r, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function makeData() {
  var sig = [], am = [], fm = [];
  var phase = -0.42;
  var prevT = 0;

  for (var i = 0; i < sampleCount; i++) {
    var t = i / (sampleCount - 1);
    var s = signalValue(t);

    sig.push({ x: t, y: 2.72 + 0.395 * s });

    var env = amEnvelope(t);
    am.push({ x: t, y: 1.46 + env * Math.sin(2 * Math.PI * 16.55 * t - 0.28) });

    if (i > 0) {
      var mid = (t + prevT) / 2;
      phase += 2 * Math.PI * fmFrequency(mid) * (t - prevT);
    }
    fm.push({ x: t, y: 0.35 + 0.365 * Math.sin(phase) });
    prevT = t;
  }
  return { sig: sig, am: am, fm: fm };
}

var waveData = makeData();

var guidePlugin = {
  id: 'amFmGuides',
  beforeDatasetsDraw: function (chart) {
    if (!overlayActive) return;
    var ctx = chart.ctx;
    var y = chart.scales.y;
    var ca = chart.chartArea;
    if (!ca) return;

    var minDim = Math.min(ca.width, ca.height);
    var radius = Math.max(2, minDim * 0.012);
    var top, bot, fill;

    if (activeMode === 'AM') {
      top = y.getPixelForValue(2.01);
      bot = y.getPixelForValue(0.91);
      fill = 'rgba(198,61,34,0.07)';
    } else {
      top = y.getPixelForValue(0.86);
      bot = y.getPixelForValue(-0.16);
      fill = 'rgba(79,102,173,0.08)';
    }

    ctx.save();
    roundedRectPath(ctx, ca.left + 4, top, ca.right - ca.left - 8, bot - top, radius);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.restore();
  },
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx;
    var x = chart.scales.x;
    var y = chart.scales.y;
    var ca = chart.chartArea;
    if (!ca) return;

    var minDim = Math.min(ca.width, ca.height);
    var lineW = Math.max(1.1, Math.min(4.2, minDim * 0.010));
    var labelFont = Math.max(12, Math.min(24, minDim * 0.046));
    var smallFont = Math.max(9, Math.min(14, minDim * 0.030));

    ctx.save();

    if (overlayActive) {
      function drawDecoded(base, amp) {
        ctx.beginPath();
        for (var i = 0; i < 360; i++) {
          var t = i / 359;
          var px = x.getPixelForValue(t);
          var py = y.getPixelForValue(base + amp * signalValue(t));
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.lineWidth = Math.max(1, lineW * 0.55);
        ctx.strokeStyle = colors.black;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.stroke();
      }

      if (activeMode === 'AM') drawDecoded(2.055, 0.125);
      else drawDecoded(0.905, 0.125);

      var markerX = x.getPixelForValue(scanT);
      ctx.beginPath();
      ctx.moveTo(markerX, ca.top + 2);
      ctx.lineTo(markerX, ca.bottom - 2);
      ctx.lineWidth = Math.max(1, lineW * 0.42);
      ctx.setLineDash([5, 4]);
      ctx.strokeStyle = 'rgba(35,35,35,0.56)';
      ctx.stroke();
      ctx.setLineDash([]);

      var sn = signalNorm(scanT);
      var readLines = [
        'signal: ' + qWord(sn, 'high', 'mid', 'low'),
        'AM height: ' + qWord(sn, 'large', 'medium', 'small'),
        'FM spacing: ' + qWord(sn, 'close', 'medium', 'wide')
      ];

      if (ca.width > 260 && ca.height > 210) {
        ctx.font = smallFont + 'px sans-serif';
        var maxW = 0;
        for (var r = 0; r < readLines.length; r++) maxW = Math.max(maxW, ctx.measureText(readLines[r]).width);
        var boxW = maxW + 14;
        var boxH = smallFont * 3.55;
        var boxX = markerX + 10;
        if (boxX + boxW > ca.right - 8) boxX = markerX - boxW - 10;
        boxX = Math.max(ca.left + 6, Math.min(ca.right - boxW - 6, boxX));
        var boxY = ca.top + 8;

        roundedRectPath(ctx, boxX, boxY, boxW, boxH, 4);
        ctx.fillStyle = 'rgba(255,255,255,0.90)';
        ctx.fill();
        ctx.strokeStyle = 'rgba(120,120,120,0.35)';
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.fillStyle = '#222';
        ctx.textBaseline = 'top';
        ctx.textAlign = 'left';
        for (var j = 0; j < readLines.length; j++) {
          ctx.fillText(readLines[j], boxX + 7, boxY + 5 + j * smallFont * 1.08);
        }
      }

      function dotAt(yv, col) {
        ctx.beginPath();
        ctx.arc(markerX, y.getPixelForValue(yv), Math.max(2, minDim * 0.007), 0, Math.PI * 2);
        ctx.fillStyle = col;
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(0.8, minDim * 0.0035);
        ctx.stroke();
      }

      dotAt(2.72 + 0.395 * signalValue(scanT), colors.black);
      if (activeMode === 'AM') {
        dotAt(1.46 + amEnvelope(scanT), colors.red);
        dotAt(1.46 - amEnvelope(scanT), colors.red);
      } else {
        dotAt(0.35 + 0.365, colors.blue);
        dotAt(0.35 - 0.365, colors.blue);
      }
    }

    ctx.font = labelFont + 'px sans-serif';
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';

    function haloLabel(txt, col, yv) {
      var px = x.getPixelForValue(1) + Math.max(8, minDim * 0.018);
      var py = y.getPixelForValue(yv);
      var w = ctx.measureText(txt).width;
      if (px + w > ca.right - 1) px = ca.right - w - 1;
      ctx.lineWidth = Math.max(3, labelFont * 0.22);
      ctx.strokeStyle = '#fff';
      ctx.lineJoin = 'round';
      ctx.strokeText(txt, px, py);
      ctx.fillStyle = col;
      ctx.fillText(txt, px, py);
    }

    haloLabel('Signal', colors.black, 2.72);
    haloLabel('AM', '#222225', 1.46);
    haloLabel('FM', '#222225', 0.35);

    ctx.restore();
  }
};

