var demoSteps = [
  {
    title: 'Compare the three traces',
    narration: 'The black curve is the slow signal to be transmitted. The red AM and blue FM traces are faster carrier waves that encode that same signal in different ways.',
    state: { timeScan: 0.25, decodingMode: 'AM' }
  },
  {
    title: 'Scan an AM crest',
    narration: 'Move the time marker under a high part of the signal. The AM wave has a large envelope height there, while its peak spacing stays uniform.',
    state: { timeScan: 0.18, decodingMode: 'AM' }
  },
  {
    title: 'Scan the signal trough',
    narration: 'At the low part of the signal, the AM envelope shrinks. In contrast, the FM wave keeps the same height but its cycles spread farther apart.',
    state: { timeScan: 0.50, decodingMode: 'FM' }
  },
  {
    title: 'Decode the same message two ways',
    narration: 'Switch the decoding mode: AM reconstructs the signal from envelope height, while FM reconstructs it from changing cycle spacing. Both carriers can recover the same black signal curve.',
    state: { timeScan: 0.75, decodingMode: 'FM' }
  }
];

function setMode(mode) {
  activeMode = mode;
  var out = document.getElementById('decodingModeVal');
  if (out) out.value = mode;
}

function update_timeScan(v) {
  scanT = Math.max(0, Math.min(1, v));
  overlayActive = true;
  chart.update('none');
}

function toggle_decodingMode(on) {
  overlayActive = true;
  setMode(on ? 'FM' : 'AM');
  chart.update();
}

function applyStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[currentStep];

  scanT = +step.state.timeScan;
  setMode(step.state.decodingMode);
  overlayActive = currentStep !== 0;

  var tInput = document.getElementById('timeScanInput');
  var tVal = document.getElementById('timeScanVal');
  var modeInput = document.getElementById('decodingModeInput');

  if (tInput) tInput.value = scanT;
  if (tVal) tVal.value = scanT.toFixed(2).replace(/0$/, '').replace(/\.0$/, '');
  if (modeInput) modeInput.checked = activeMode === 'FM';

  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (label) label.textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;

  chart.update(currentStep === 0 ? 'none' : undefined);
}
function prevStep() { applyStep(currentStep - 1); }
function nextStep() { applyStep(currentStep + 1); }

applyStep(0);

canvas.addEventListener('mousemove', function (event) {
  var rect = canvas.getBoundingClientRect();
  var yPix = event.clientY - rect.top;
  var xPix = event.clientX - rect.left;
  var ca = chart.chartArea;

  if (!ca || xPix < ca.left || xPix > ca.right || yPix < ca.top || yPix > ca.bottom) {
    hideTooltip();
    canvas.style.cursor = 'default';
    return;
  }

  var yVal = chart.scales.y.getValueForPixel(yPix);
  var text;
  if (yVal > 2.12) {
    text = 'Signal: the slow information waveform that both carriers encode.';
  } else if (yVal > 0.90) {
    text = 'AM: peak spacing stays nearly uniform, while carrier height follows the signal.';
  } else {
    text = 'FM: height stays nearly constant, while cycle spacing follows the signal.';
  }
  canvas.style.cursor = 'pointer';
  showTooltip(text, event);
});
canvas.addEventListener('mouseleave', function () {
  hideTooltip();
  canvas.style.cursor = 'default';
});
canvas.addEventListener('click', function (event) {
  var rect = canvas.getBoundingClientRect();
  var yPix = event.clientY - rect.top;
  var yVal = chart.scales.y.getValueForPixel(yPix);

  if (yVal > 0.90 && yVal < 2.12) {
    overlayActive = true;
    setMode('AM');
    var modeInputA = document.getElementById('decodingModeInput');
    if (modeInputA) modeInputA.checked = false;
    chart.update();
    showPopup('Amplitude modulation', 'AM stores the message in the carrier height. The red carrier peaks stay evenly spaced, but their envelope swells and shrinks with the black signal.');
  } else if (yVal <= 0.90) {
    overlayActive = true;
    setMode('FM');
    var modeInputF = document.getElementById('decodingModeInput');
    if (modeInputF) modeInputF.checked = true;
    chart.update();
    showPopup('Frequency modulation', 'FM stores the message in the spacing of the carrier cycles. The blue wave keeps nearly constant height, but cycles compress at signal crests and spread out near troughs.');
  } else {
    showPopup('Shared signal', 'The black waveform is the information signal. AM and FM encode this same shape using different carrier properties.');
  }
});
